 if(a==='night'){if(!pay(PLC_PRICE.night,'hotel-night'))return;try{gameClockSet(7,0)}catch(e){}PLC.n.night++;setPhoneOpen(false);let ok=false;try{ok=!!(SaveManager.save('manual-hotel')||{}).ok}catch(e){}toast('🛏 ישנת במלון הכיכר · 07:00 · '+(ok?'המשחק נשמר':'השמירה לא הצליחה'));return}
