function wtcPass0(list,G,now,miss){
 const B=ctx.getTransform();ctx.setTransform(1,0,0,1,0,0);const lost=[],zpBase=list.length&&(list[0][0]==='M'||list[0][0]==='L0');   /* D-225 · p295 */
 for(const [layer,i,j] of list){const t=WTC.tiles.get(layer+'|'+G.key+'|'+i+'|'+j);if(!t&&WTC_EMPTY.has(layer+'|'+G.key+'|'+i+'|'+j))continue;if(t){t.last=WTC.frame;if(t.cv){const b=t.bb;if(G.k===1){if(b)wtcBlit(t.cv,b[0],b[1],b[2],b[3],i*G.T+G.ox+b[0],j*G.T+G.oy+b[1],b[2],b[3]);else wtcBlit(t.cv,0,0,G.T,G.T,i*G.T+G.ox,j*G.T+G.oy,G.T,G.T)}
   else{const q=G.tw*G.sd,X0=Math.round(i*q+G.cx),Y0=Math.round(j*q+G.cy),kx=(Math.round((i+1)*q+G.cx)-X0)/G.T,ky=(Math.round((j+1)*q+G.cy)-Y0)/G.T;if(b)wtcBlit(t.cv,b[0],b[1],b[2],b[3],X0+b[0]*kx,Y0+b[1]*ky,b[2]*kx,b[3]*ky);else wtcBlit(t.cv,0,0,G.T,G.T,X0,Y0,G.T*kx,G.T*ky)}   /* 25.10 · p317: only the part on the screen */   /* K-163 · p268: a level tile, scaled to the screen (the edges rounded once — no seams) */WTC.stats.drawn++}}else lost.push([layer,i,j])}
 ctx.setTransform(B);
 if(zpBase&&!lost.length)G77_ZP.full={key:G.key,tw:G.tw};   /* D-225 · p295: the last level with all its tiles */
 if(lost.length&&WTC.prev){const keep=[];for(const q of lost){if(!wtcPrevCover(q,G))keep.push(q)}lost.length=0;lost.push(...keep)}
 if(lost.length&&G77_ZP.on&&G77_ZP.full&&G77_ZP.full.key!==G.key&&(!WTC.prev||G77_ZP.full.key!==WTC.prev.key)){const P0=WTC.prev;WTC.prev=G77_ZP.full;try{const keep=[];for(const q of lost){if(!wtcPrevCover(q,G))keep.push(q)}if(keep.length<lost.length)G77_ZP.stats.fullCover+=lost.length-keep.length;lost.length=0;lost.push(...keep)}finally{WTC.prev=P0}}   /* D-225 · p295 */
 if(lost.length&&WTC.mapFill&&MAPBASE.done&&MAPBASE.levels){const keep=[];for(const q of lost){if(!wtcMapCover(q,G))keep.push(q)}lost.length=0;lost.push(...keep)}
 if(lost.length&&typeof G77_PHS!=='undefined'&&G77_PHS.under){G77_PHS.lostSkip+=lost.length;lost.length=0}   /* D-226 · p316: not seen under the phone */for(const layer of ['M','L0','L1','T']){const L=lost.filter(q=>q[0]===layer);if(!L.length)continue;WTC.stats.fallbackTiles+=L.length;miss.n+=L.length;
  let x0=1e9,y0=1e9,x1=-1e9,y1=-1e9;ctx.save();ctx.beginPath();for(const [,i,j] of L){const X=i*G.tw,Y=j*G.tw;ctx.rect(X,Y,G.tw,G.tw);x0=Math.min(x0,X);y0=Math.min(y0,Y);x1=Math.max(x1,X+G.tw);y1=Math.max(y1,Y+G.tw)}ctx.clip();
  const pv=VIEW_OVR,pm=WTC_MODE,pmu=Targets.mute;VIEW_OVR={cx:(x0+x1)/2,cy:(y0+y1)/2,hw:(x1-x0)/2+WTC.margin,hh:(y1-y0)/2+WTC.margin};WTC_MODE=1;Targets.mute=true;WTC.ctxBuilding=ctx;
  try{if(layer==='T')wtcPaintL2(now);else if(layer==='L0')wtcPaintL0(now);else if(layer==='L1')wtcPaintL1(now);else{wtcPaintL0(now);wtcPaintL1(now)}}catch(e){if(!WTC.err){WTC.err=String(e&&e.stack||e);console.error('world tile fallback',e)}}finally{VIEW_OVR=pv;WTC_MODE=pm;Targets.mute=pmu;WTC.ctxBuilding=null}
  ctx.restore()}}
